DROP POLICY IF EXISTS "templates read" ON public.project_templates; DROP POLICY IF EXISTS "templates write" ON public.project_templates; DROP POLICY IF EXISTS "template_jobs read" ON public.project_template_jobs; DROP POLICY IF EXISTS "template_jobs write" ON public.project_template_jobs; DROP POLICY IF EXISTS "template_tasks read" ON public.project_template_tasks; DROP POLICY IF EXISTS "template_tasks write" ON public.project_template_tasks;
CREATE POLICY "template_jobs read" ON public.project_template_jobs FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.project_templates t WHERE t.id=template_id AND (t.is_system OR (t.brand_id IS NOT NULL AND public.is_brand_member(t.brand_id,auth.uid()) AND (t.source_client_id IS NULL OR public.can_access_client(t.source_client_id,auth.uid()))))));
CREATE POLICY "template_jobs write" ON public.project_template_jobs FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.project_templates t WHERE t.id=template_id AND NOT t.is_system AND t.brand_id IS NOT NULL AND public.is_brand_member(t.brand_id,auth.uid()) AND (t.source_client_id IS NULL OR public.can_access_client(t.source_client_id,auth.uid())))) WITH CHECK (EXISTS(SELECT 1 FROM public.project_templates t WHERE t.id=template_id AND NOT t.is_system AND t.brand_id IS NOT NULL AND public.is_brand_member(t.brand_id,auth.uid()) AND (t.source_client_id IS NULL OR public.can_access_client(t.source_client_id,auth.uid()))));
CREATE POLICY "template_tasks read" ON public.project_template_tasks FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.project_template_jobs j JOIN public.project_templates t ON t.id=j.template_id WHERE j.id=template_job_id AND (t.is_system OR (t.brand_id IS NOT NULL AND public.is_brand_member(t.brand_id,auth.uid()) AND (t.source_client_id IS NULL OR public.can_access_client(t.source_client_id,auth.uid()))))));
CREATE POLICY "template_tasks write" ON public.project_template_tasks FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.project_template_jobs j JOIN public.project_templates t ON t.id=j.template_id WHERE j.id=template_job_id AND NOT t.is_system AND t.brand_id IS NOT NULL AND public.is_brand_member(t.brand_id,auth.uid()) AND (t.source_client_id IS NULL OR public.can_access_client(t.source_client_id,auth.uid())))) WITH CHECK (EXISTS(SELECT 1 FROM public.project_template_jobs j JOIN public.project_templates t ON t.id=j.template_id WHERE j.id=template_job_id AND NOT t.is_system AND t.brand_id IS NOT NULL AND public.is_brand_member(t.brand_id,auth.uid()) AND (t.source_client_id IS NULL OR public.can_access_client(t.source_client_id,auth.uid()))));
REVOKE EXECUTE ON FUNCTION public.save_project_template(uuid,uuid,text,text,jsonb,uuid) FROM authenticated;